package com.quiz.servlet;
import com.quiz.dao.*; import com.quiz.model.*; import java.io.*; import java.sql.SQLException; import java.util.*; import javax.servlet.*; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*;
@WebServlet("/assessment/submit") public class SubmitAssessmentServlet extends HttpServlet {private final QuizDAO qd=new QuizDAO();private final ResultDAO rd=new ResultDAO();protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{HttpSession s=req.getSession(false);User u=s==null?null:(User)s.getAttribute("user");if(u==null){resp.sendRedirect(req.getContextPath()+"/login");return;}try{int id=Integer.parseInt(req.getParameter("quizId"));Quiz quiz=qd.findPublishedById(id);if(quiz==null||quiz.isOverdue()||rd.hasAssessmentAttempt(u.getId(),id)){resp.sendRedirect(req.getContextPath()+"/student/dashboard");return;}List<Question> qs=qd.findQuestions(id);int score=0;List<QuestionReview> reviews=new ArrayList<>();for(Question q:qs){QuestionReview r=new QuestionReview(q,req.getParameter("q_"+q.getId()));if(r.isCorrect())score++;reviews.add(r);}int resultId=rd.saveAssessment(u.getId(),quiz,score,qs.size());if(quiz.isPractice()){s.setAttribute("lastReviewResultId",resultId);s.setAttribute("lastReviews",reviews);}else{s.removeAttribute("lastReviewResultId");s.removeAttribute("lastReviews");}resp.sendRedirect(req.getContextPath()+"/result?id="+resultId);}catch(Exception e){throw new ServletException("Could not submit assessment",e);}}}
